def floodfill_interior_transformation(grid):
    h, w = len(grid), len(grid[0])

    # Step 1: Mark exterior 0s as 2 via boundary flood fill
    visited_exterior = [[False]*w for _ in range(h)]
    queue = deque()
    for r in range(h):
        if grid[r][0] == 0: queue.append((r,0))
        if grid[r][w-1] == 0: queue.append((r,w-1))
    for c in range(w):
        if grid[0][c] == 0: queue.append((0,c))
        if grid[h-1][c] == 0: queue.append((h-1,c))

    while queue:
        r, c = queue.popleft()
        if visited_exterior[r][c]: continue
        visited_exterior[r][c] = True
        grid[r][c] = 2
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not visited_exterior[nr][nc]:
                queue.append((nr, nc))

    # Step 2: Find interior 0s and group into components
    interior_0s = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and not visited_exterior[r][c]:
                interior_0s.append((r,c))

    # Step 3: Group into connected components via BFS
    seen_in_component = set()
    components = []
    for start in interior_0s:
        if start in seen_in_component: continue
        comp = [start]
        queue = [start]
        seen_in_component.add(start)
        while queue:
            cr, cc = queue.pop(0)
            for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if grid[nr][nc] == 0 and (nr, nc) not in seen_in_component and not visited_exterior[nr][nc]:
                        seen_in_component.add((nr, nc))
                        comp.append((nr, nc))
                        queue.append((nr, nc))
        components.append(comp)

    print(f"Found {len(components)} interior components")

    # Step 4: Calculate centers and transform
    new_grid = [row[:] for row in grid]
    for comp in components:
        rows = [r for r, c in comp]
        cols = [c for r, c in comp]
        center_r = round(sum(rows)/len(rows))
        center_c = round(sum(cols)/len(cols))
